import urllib.request, json; req = urllib.request.Request('http://localhost:8000/auth/login', data=json.dumps({'email':'admin@example.com', 'password':'admin'}).encode('utf-8'), headers={'Content-Type': 'application/json'}); res = urllib.request.urlopen(req); token = json.loads(res.read())['access_token']; req2 = urllib.request.Request('http://localhost:8000/groups', headers={'Authorization': 'Bearer ' + token}); res2 = urllib.request.urlopen(req2); groups = json.loads(res2.read()); group_id = groups[0]['group_id'] if groups else None; print('Group:', group_id); req3 = urllib.request.Request(f'http://localhost:8000/groups/{group_id}/files', headers={'Authorization': 'Bearer ' + token}); res3 = urllib.request.urlopen(req3); print(res3.read())  
